import java.util.ArrayList;
import java.util.List;

public class EnrolledStudent {
    // 1. Static sequence counter (shared across all instances)
    private static int counter = 0;

    // 2. Instance variables (unique to each instance)
    private final String studentId;
    private String name;
    private String email;

    public EnrolledStudent(String name, String email) {
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Student name cannot be empty.");
        }
        this.studentId = String.format("STU-2026-%04d", ++counter);
        this.name = name.trim();
        this.email = (email != null) ? email.trim() : "unknown@campus.edu";
    }

    public static int getTotalStudentsCreated() {
        return counter;
    }

    public String getStudentId() { return studentId; }
    public String getName() { return name; }
    public String getEmail() { return email; }
}

class CourseSection {
    // 3. Static constants and shared metrics
    public static final int MAX_CAPACITY = 3;
    private static int totalEnrollments = 0;

    // Instance variables
    private String courseCode;
    private String courseTitle;
    private List<EnrolledStudent> enrolledStudents;

    public CourseSection(String courseCode, String courseTitle) {
        this.courseCode = courseCode;
        this.courseTitle = courseTitle;
        this.enrolledStudents = new ArrayList<>();
    }

    // 4. Capacity-guarded enrollment
    public boolean enroll(EnrolledStudent student) {
        if (student == null) return false;
        if (enrolledStudents.size() >= MAX_CAPACITY) {
            System.err.printf("Error: Cannot enroll %s. Section %s is full (MAX: %d).%n", 
                student.getName(), courseCode, MAX_CAPACITY);
            return false;
        }
        enrolledStudents.add(student);
        totalEnrollments++;
        System.out.printf("Enrolled %s (%s) into %s successfully.%n", 
            student.getName(), student.getStudentId(), courseCode);
        return true;
    }

    public static int getTotalEnrollments() {
        return totalEnrollments;
    }

    public void printRoster() {
        System.out.println("=======================================================");
        System.out.printf("        COURSE SECTION ROSTER: %s%n", courseCode);
        System.out.printf("        %s%n", courseTitle);
        System.out.println("=======================================================");
        System.out.printf("Capacity: %d | Enrolled: %d | Status: %s%n",
            MAX_CAPACITY, enrolledStudents.size(), 
            (enrolledStudents.size() >= MAX_CAPACITY ? "FULL" : "SEATS AVAILABLE"));
        System.out.println("-------------------------------------------------------");
        for (int i = 0; i < enrolledStudents.size(); i++) {
            EnrolledStudent s = enrolledStudents.get(i);
            System.out.printf(" %d. %s | %-16s | %s%n", i + 1, s.getStudentId(), s.getName(), s.getEmail());
        }
        System.out.println("=======================================================\n");
    }
}

